import { Component, EventEmitter, inject, Input, OnDestroy, OnInit, Output } from '@angular/core';
import { MessageConfig, MessageModule } from 'espd-common/i18n';
import { IconDirective } from 'espd-common/icon';
import { ActionList, NoAction, SectionActionsComponent, SingleAction } from 'espd-common/layout/actions';
import { CollapseModule } from 'ngx-bootstrap/collapse';
import { AccordionComponent } from '../accordion/accordion.component';

@Component({
	selector: 'espd-accordion-panel',
	templateUrl: './accordion-panel.component.html',
	styleUrl: './accordion-panel.component.scss',
	host: {
		style: 'display: block'
	},
	imports: [
		SectionActionsComponent,
		CollapseModule,
		IconDirective,
		MessageModule
	]
})
export class AccordionPanelComponent implements OnInit, OnDestroy {
	private static nextId = 0;

	/** turn on/off animation */
	isAnimated = true;

	/** Clickable text in accordion's panel header */
	@Input() public heading!: MessageConfig | string;

	@Input() public actions: ActionList | SingleAction | NoAction = null;

	/** Emits when the opened state changes */
	@Output() readonly isOpenChange = new EventEmitter<boolean>();

	/** Is accordion group open or closed. This property supports two-way binding */
	@Input()
	get isOpen(): boolean {
		return this._isOpen;
	}

	set isOpen(value: boolean) {
		if (value !== this.isOpen) {
			if (value) {
				this.accordion.closeOtherPanels(this);
			}
			this._isOpen = value;
			setTimeout(() => {
				this.isOpenChange.emit(value);
			});
		}
	}

	public id = AccordionPanelComponent.nextId++;

	private _isOpen = false;
	private accordion = inject(AccordionComponent);

	public ngOnInit(): void {
		this.accordion.addPanel(this);
	}

	public ngOnDestroy(): void {
		this.accordion.removePanel(this);
	}

	public toggleOpen(): void {
		this.isOpen = !this.isOpen;
	}
}